#include <iostream>
#include <stdexcept>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        throw std::invalid_argument{"Quantité hors de 0 à 10"};
    }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int main() {
    try {
        int minutos{estimar(2)};
        std::cout << minutos;
    } catch (const std::invalid_argument& error) {
        std::cout << "Commande invalide";
    }
    std::cout << ":Fin";
    return 0;
}

